      const { req } = createMocks({
        method: 'POST',
        headers: { 
          'authorization': 'Bearer valid-token',
        },
        body: formData,
      });

      const response = await uploadHandler(req as any);
      expect(response.status).toBe(400);
    });

    it('rejects SVG with script tags', async () => {
