        data: { user: { id: 'user-123' } },
        error: null,
      });

      const maliciousSvg = `<svg onload="alert('xss')"><rect width="100" height="100"/></svg>`;
      const svgFile = new File([maliciousSvg], 'avatar.svg', { type: 'image/svg+xml' });
